import { useState } from 'react';
import './DifficultySelection.css'
function DifficultySelection(props) {

    const[showDifficulty, setShowDifficulty] = useState(false);

    return (
        <div style = {{display:'flex'}}>
            {showDifficulty 
                && 
                <>
                <button className='level' onClick={() => props.difficultyChange(10)}> 10 </button>
                <button className='level' onClick={() => props.difficultyChange(20)}> 20 </button>
                </>}
            <button className="DS" onClick={()=>setShowDifficulty(!showDifficulty)}/>
        </div>
    )
}

export default DifficultySelection;
